/**
 * Sound Synthesis - Procedural sound effect generation using Web Audio API
 */
class SoundSynth {
    constructor(audioContext) {
        this.audioContext = audioContext;
    }

    play(name, params = {}, gainNode) {
        const synth = new Oscillator(this.audioContext);

        switch (name) {
            case 'explosion':
                return this._playExplosion(synth, params, gainNode);
            case 'laser':
                return this._playLaser(synth, params, gainNode);
            case 'powerup':
                return this._playPowerUp(synth, params, gainNode);
            case 'hit':
                return this._playHit(synth, params, gainNode);
            default:
                return null;
        }
    }

    _playExplosion(synth, params, gainNode) {
        const duration = params.duration || 0.5;
        const volume = params.volume || 1.0;

        // Create noise for explosion effect
        const bufferSize = this.audioContext.sampleRate * duration;
        const buffer = this.audioContext.createBuffer(1, bufferSize);
        const data = buffer.getChannelData(0);

        for (let i = 0; i < bufferSize; i++) {
            // White noise with exponential decay envelope
            const t = i / bufferSize;
            const envelope = Math.exp(-t * duration * 4);
            data[i] = (Math.random() - 0.5) * envelope * volume;
        }

        const source = this.audioContext.createBufferSource();
        source.buffer = buffer;

        // Add filter for low-pass effect
        const filter = this.audioContext.createBiquadFilter();
        filter.type = 'lowpass';
        filter.frequency.value = 2000;
        filter.Q.value = 1.5;

        source.connect(filter);
        filter.connect(gainNode);

        source.start(params.startTime || 0);
        return source;
