        gradient.addColorStop(1, 'rgba(0, 0, 0, 0)');

        // Draw glow pattern
        ctx.fillStyle = gradient;
        ctx.fillRect(0, 0, width, height);

        this.cache[key] = canvas;
        return canvas;
    }

