            const button = gamepad.buttons[i];
            if (button.pressed && !this.actions[`gamepad_${i}`]) {
                this.actions[`gamepad_${i}`] = true;
            } else if (!button.pressed && this.actions[`gamepad_${i}`]) {
                this.actions[`gamepad_${i}`] = false;
            }
        }
