        if (!this.isPlaying) return;

        // Fade out and stop all oscillators
        this._oscillators.forEach(oscillator => {
            oscillator.stop();
        });

        this._gainNodes.forEach(gainNode => {
            gainNode.disconnect();
        });

        clearInterval(this._updateInterval);
        this.isPlaying = false;
