        this._gameLoop();
    }

    _gameLoop() {
        requestAnimationFrame(() => {
            this._update();
            this._render();
            this._gameLoop();
        });
    }

    _update() {
        const deltaTime = 1 / 60; // Fixed timestep

        // Update input manager
        this.inputManager.update();

        // Update game state based on current mode
        switch(this.state) {
            case 'menu':
                this._updateMenu();
                break;
            case 'playing':
                this._updateGameplay(deltaTime);
