        requestAnimationFrame(() => {
            this._update();
            this._render();
            this._gameLoop();
        });
    }

    _update() {
        const deltaTime = 1 / 60; // Fixed timestep

        // Update input manager
        this.inputManager.update();

        // Update game state
        this.game.update(deltaTime);
    }

    _render() {
        // Render scene with all entities and effects
        this.scene.render(this.game.entities, this.game.cameraShakeSystem);
    }

    destroy() {
        // Clean up resources
        this.inputManager.destroy();
        this.scene.destroy();
        this.game.destroy();

        // Clear references
        this.container = null;
        this.inputManager = null;
        this.scene = null;
        this.game = null;
    }
}

