            'a': 'left',
            's': 'right',
            'd': 'right',
            ' ': 'fire',
            'Enter': 'start'
        };

        const action = actionMap[key.toLowerCase()];
        if (action) {
            this.actions[action] = true;
        }
    }

    _clearAction(key) {
        const actionMap = {
            'ArrowLeft': 'left',
            'ArrowRight': 'right',
            'w': 'left',
            'a': 'left',
            's': 'right',
            'd': 'right',
            ' ': 'fire',
            'Enter': 'start'
        };

        const action = actionMap[key.toLowerCase()];
        if (action) {
