                    this.cameraShakeSystem.triggerShake(0.3, 0.2);

                    // Remove projectile and enemy
                    this.projectiles.splice(i, 1);
                    this.enemies.splice(j, 1);

                    i--; j = -1;
                }
            }
        }

        // Update particles
        for (let i = this.particles.length - 1; i >= 0; i--) {
            const particle = this.particles[i];

            if (!particle.update(deltaTime)) {
                this.particles.splice(i, 1);
            }
        }

        // Check win condition (all enemies destroyed)
        if (this.enemies.length === 0) {
            this.level++;
            this._spawnEnemies();
        }

        // Check game over condition
        if (this.lives <= 0) {
            this.state = 'gameover';
        }
    }

    _updateGameOver() {
        if (this.inputManager.isActionActive('start')) {
            this._resetGame();
        }
    }

    _resetGame() {
        // Reset game state and entities
        this.score = 0;
        this.lives = 3;
        this.level = 1;

        // Clear all enemies and projectiles
        this.enemies = [];
        this.projectiles = [];
        this.particles = [];

        // Reinitialize game objects
        this._initializeGame();

        this.state = 'playing';
    }

    destroy() {
        // Dispose of resources
        if (this.player) {
            this.player.dispose();
        }

        for (let i = 0; i < this.enemies.length; i++) {
            this.enemies[i].dispose();
        }

        for (let i = 0; i < this.projectiles.length; i++) {
            this.projectiles[i].dispose();
        }

        // Clear references
        this.player = null;
        this.enemies = [];
        this.projectiles = [];
        this.particles = [];
    }
}

export default Game;
EOF

